def shipping_cost(weight_kg):
    return min(25, 5 + 2 * weight_kg)

def tax(amount, region):
    return amount * {"EU": 0.20, "US": 0.07}.get(region, 0.15)

def discount_code(code):
    return {"WELCOME10": 0.10, "VIP20": 0.20}.get(code, 0.0)

def total(subtotal, weight_kg, region, code):
    discounted = subtotal * (1 - discount_code(code))
    return round(discounted * (1 + tax(1, region)) + shipping_cost(weight_kg), 2)

def can_express(region, weight_kg):
    return weight_kg <= 20 and region != "AU"

def free_shipping(total_amount, region):
    return region == "US" and total_amount >= 50

def split_billing(total_amount, people):
    share = round(total_amount / people, 2)
    last = round(total_amount - share * (people - 1), 2)
    return share, last

def currency(amount):
    return "%.2f USD" % amount

